def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # All objective-consistent pairs (lower is better): winner has lower objective.
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Nonnegative weight based on objective gap; configurable floor to avoid zeroing near-ties.
    gap_floor = 0.0
    if extra is not None and 'gap_floor' in extra and extra['gap_floor'] is not None:
        gap_floor = float(extra['gap_floor'])
        if gap_floor < 0.0:
            gap_floor = 0.0

    gaps = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    weight = gaps
    if gap_floor > 0.0:
        weight = weight + gap_floor

    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_floor': gap_floor})

def generated_builder(feature_cache, extra):
